from lib import *
E, M, S, H = 'easy', 'medium', 'sufficient', 'hard'

def dyn(mx, step, lab):
    return {"kind": "scale", "instrument": "dynamometer", "min": 0, "max": mx, "step": step, "label": lab, "value": 'f', "unit": 'Н'}

# A cube fully submerged in a vessel 30 units deep: edge 10, top at depth `dep`.
SUB = {"kind": "vessel", "h": 30, "body": {"size": 10, "depth": 'dep'}, "labels": {"liquid": 'вода', "body": 'V'}}

T = []
